#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const { sendMessage } = require('../event_handler/tools/telegram');

async function main() {
  // Check for required environment variables
  const TELEGRAM_BOT_TOKEN = process.env.TELEGRAM_BOT_TOKEN;
  const TELEGRAM_CHAT_ID = process.env.TELEGRAM_CHAT_ID;

  if (!TELEGRAM_BOT_TOKEN) {
    console.error('❌ Error: TELEGRAM_BOT_TOKEN not found in environment');
    console.log('Available environment variables:');
    console.log(Object.keys(process.env).filter(k => k.includes('TELEGRAM')).join(', '));
    process.exit(1);
  }

  if (!TELEGRAM_CHAT_ID) {
    console.error('❌ Error: TELEGRAM_CHAT_ID not found in environment');
    console.log('Please set TELEGRAM_CHAT_ID in your secrets');
    process.exit(1);
  }

  // Read the briefing
  const briefingPath = path.join(__dirname, 'sterling_briefing.md');
  const briefing = fs.readFileSync(briefingPath, 'utf-8');

  // Convert Markdown to HTML (simple conversion)
  let html = briefing
    // Headers
    .replace(/^# (.*?)$/gm, '<b>$1</b>')
    .replace(/^## (.*?)$/gm, '<b>$1</b>')
    .replace(/^### (.*?)$/gm, '<b>$1</b>')
    // Bold
    .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
    // Italic
    .replace(/\*(.*?)\*/g, '<i>$1</i>')
    // Code blocks (remove backticks, Telegram HTML doesn't support complex code formatting)
    .replace(/`(.*?)`/g, '<code>$1</code>')
    // Horizontal rules
    .replace(/^---$/gm, '━━━━━━━━━━━━━━━━━━━━')
    // List items (keep simple)
    .replace(/^- (.*?)$/gm, '  • $1')
    .replace(/^\d+\. (.*?)$/gm, '  $1')
    // Clean up extra newlines
    .replace(/\n{3,}/g, '\n\n');

  try {
    console.log('📤 Sending Sterling Intelligence Briefing to Telegram...');
    console.log(`Chat ID: ${TELEGRAM_CHAT_ID}`);

    const result = await sendMessage(
      TELEGRAM_BOT_TOKEN,
      TELEGRAM_CHAT_ID,
      html,
      { disablePreview: true }
    );

    console.log('✅ Briefing sent successfully!');
    console.log(`Message ID: ${result.message_id}`);

  } catch (error) {
    console.error('❌ Error sending briefing:', error.message);
    if (error.response) {
      console.error('Response:', error.response);
    }
    process.exit(1);
  }
}

main();

