#!/usr/bin/env node

/**
 * Send a message to Telegram
 * 
 * Usage:
 *   node telegram-send.js <file-path>
 *   node telegram-send.js --text "message"
 *   echo "message" | node telegram-send.js --stdin
 * 
 * Environment variables required:
 *   TELEGRAM_BOT_TOKEN - Bot token from @BotFather
 *   TELEGRAM_CHAT_ID - Chat ID to send to
 */

const fs = require('fs');
const https = require('https');

function sendTelegramMessage(token, chatId, text) {
  return new Promise((resolve, reject) => {
    // Strip HTML comments
    text = text.replace(/<!--[\s\S]*?-->/g, '');

    // Telegram API limit
    const MAX_LENGTH = 4096;

    // Split if needed
    const chunks = [];
    while (text.length > 0) {
      if (text.length <= MAX_LENGTH) {
        chunks.push(text);
        break;
      }

      let splitAt = MAX_LENGTH;
      const chunk = text.slice(0, MAX_LENGTH);

      // Try to split at natural boundaries
      for (const delim of ['\n\n', '\n', '. ', ' ']) {
        const idx = chunk.lastIndexOf(delim);
        if (idx > MAX_LENGTH * 0.3) {
          splitAt = idx + delim.length;
          break;
        }
      }

      chunks.push(text.slice(0, splitAt).trimEnd());
      text = text.slice(splitAt).trimStart();
    }

    // Send all chunks
    const sendChunk = (index) => {
      if (index >= chunks.length) {
        resolve({ chunks: chunks.length });
        return;
      }

      const postData = JSON.stringify({
        chat_id: chatId,
        text: chunks[index],
        parse_mode: 'HTML',
        link_preview_options: { is_disabled: true }
      });

      const options = {
        hostname: 'api.telegram.org',
        path: `/bot${token}/sendMessage`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          if (res.statusCode === 200) {
            console.log(`✅ Sent chunk ${index + 1}/${chunks.length}`);
            sendChunk(index + 1);
          } else {
            reject(new Error(`HTTP ${res.statusCode}: ${data}`));
          }
        });
      });

      req.on('error', reject);
      req.write(postData);
      req.end();
    };

    sendChunk(0);
  });
}

async function main() {
  const args = process.argv.slice(2);

  // Check for required env vars
  const token = process.env.TELEGRAM_BOT_TOKEN;
  const chatId = process.env.TELEGRAM_CHAT_ID;

  if (!token || !chatId) {
    console.error('❌ Missing required environment variables:');
    if (!token) console.error('  - TELEGRAM_BOT_TOKEN');
    if (!chatId) console.error('  - TELEGRAM_CHAT_ID');
    console.error('\nThese should be set in your SECRETS or LLM_SECRETS.');
    process.exit(1);
  }

  // Get message text
  let text;

  if (args[0] === '--text') {
    text = args.slice(1).join(' ');
  } else if (args[0] === '--stdin') {
    text = fs.readFileSync(0, 'utf-8');
  } else if (args[0]) {
    text = fs.readFileSync(args[0], 'utf-8');
  } else {
    console.error('Usage:');
    console.error('  node telegram-send.js <file-path>');
    console.error('  node telegram-send.js --text "message"');
    console.error('  echo "message" | node telegram-send.js --stdin');
    process.exit(1);
  }

  if (!text || !text.trim()) {
    console.error('❌ No message text provided');
    process.exit(1);
  }

  console.log('📤 Sending to Telegram...');
  console.log(`   Chat ID: ${chatId}`);
  console.log(`   Length: ${text.length} chars`);

  try {
    const result = await sendTelegramMessage(token, chatId, text);
    console.log(`\n✅ Success! Sent ${result.chunks} message(s)`);
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    process.exit(1);
  }
}

main();

